INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "李思安进攻幽州，被刘守光击退", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年三月至四月己酉", "dynasty": "唐末五代十国", "description": "李思安奉梁王命领兵进攻幽州。四月抵城时刘仁恭不在城中，刘守光入城拒守并击退李思安。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "fd713cf1-2518-5245-bb40-1fc7ade58200"}, {"title": "唐廷与各镇相继向梁王劝进", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年二月至三月", "dynasty": "唐末五代十国", "description": "唐廷组织百官劝进，三月再遣使传达禅位之意，并安排册礼、传国宝与金宝的奉送人员。杨凝式劝父杨涉辞去送玺之事。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "0ca868ec-69c8-5cb8-81c7-96f889349aab"}, {"title": "钱氏军队攻取温州，卢佶被杀", "start_year": 907, "end_year": 907, "time_original": "907年正月至四月（吴越备史记正月出兵，通鉴记三月出兵；四月取温州）", "dynasty": "唐末五代十国", "description": "钱镠遣钱传镣、钱传瓘讨卢佶。钱传瓘避开青澳守军，自安固取道袭温州，城破后卢佶被擒杀；吴璋受命处理温州事务，钱氏军队转攻处州。", "phases": [], "location_name": "温州、青澳、安固", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "7a6b4f25-ef47-587b-8117-559fb13360bb"}, {"title": "杨凝式劝父杨涉辞送玺之事", "start_year": 907, "end_year": 907, "time_original": "907年三月甲辰后；确日未载", "dynasty": "唐", "description": "杨凝式劝父杨涉辞送玺之事。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "d15c6b70-2587-5235-88ca-3d350673f399"}, {"title": "刘仁恭于大安山筑馆并求长生", "start_year": null, "end_year": null, "time_original": "907年前后；筑馆确年未载", "dynasty": "唐", "description": "刘仁恭于大安山筑馆并求长生。", "phases": [], "location_name": "大安山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "467d3d15-1ed4-5862-9076-6f1cbfa8fc7a"}, {"title": "刘仁恭敛钱并限制茶商入境", "start_year": null, "end_year": null, "time_original": "907年前后；施行起讫未载", "dynasty": "唐", "description": "刘仁恭敛钱并限制茶商入境。", "phases": [], "location_name": "幽州境内", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dd4ba249-706e-5218-bde3-c1e91758b7a0"}, {"title": "刘仁恭因守光与罗氏私通而杖斥守光", "start_year": null, "end_year": null, "time_original": "李思安攻幽州前；确年日未载", "dynasty": "唐", "description": "刘仁恭因守光与罗氏私通而杖斥守光。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "8e26326a-b3b7-587d-9957-b7f4ae52dfcd"}, {"title": "刘守光夺取卢龙军权并囚禁刘仁恭", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月条", "dynasty": "唐末五代十国", "description": "刘守光击退李思安后自称节度使，遣李小喜、元行钦进攻大安山，擒获并囚禁父亲刘仁恭。", "phases": [], "location_name": "幽州、大安山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "22048b33-cfe1-5c36-a174-6cac13729ef7"}, {"title": "刘守光杀刘仁恭身边其所恶之人", "start_year": 907, "end_year": 907, "time_original": "刘仁恭被囚后；确日未载", "dynasty": "唐", "description": "刘守光杀刘仁恭身边其所恶之人。", "phases": [], "location_name": "幽州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b2a96fec-985f-5da6-bd24-33564be836de"}, {"title": "王思同、李承约等离开幽州投奔河东", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月条，先后间隔未详", "dynasty": "唐末五代十国", "description": "刘守光夺权后，王思同、李承约率部投奔河东；刘守奇先奔契丹，后亦奔河东。李克用任命李承约与王思同。", "phases": [], "location_name": "河东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "680a4b8a-83ef-57ac-86e5-4f6b95143d3b"}, {"title": "梁王受百官称臣，下令公文去唐年号", "start_year": 907, "end_year": 907, "time_original": "唐天祐四年四月庚戌、辛亥", "dynasty": "唐末五代十国", "description": "梁王在金祥殿受百官称臣，随后令笺表簿籍去除唐年号，仅记月日。", "phases": [], "location_name": "金祥殿", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "历史地名与今地的对应尚待考证。", "status": "draft", "id": "68302e6d-1846-562c-97c5-ddef4dc41044"}, {"title": "张文蔚等奉禅位册礼到大梁", "start_year": 907, "end_year": 907, "time_original": "907年四月丙辰", "dynasty": "唐", "description": "张文蔚等奉禅位册礼到大梁。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3d29bc38-9e9e-5e62-86f2-b72722420b06"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

